# Icon restore script - writes the fixed public\index.html directly
# Run from the project folder (C:\Users\1\LOOKLI)

$b64 = ""
$bytes = [Convert]::FromBase64String($b64)
$msIn = New-Object System.IO.MemoryStream(,$bytes)
$gzip = New-Object System.IO.Compression.GzipStream($msIn, [System.IO.Compression.CompressionMode]::Decompress)
$msOut = New-Object System.IO.MemoryStream
$gzip.CopyTo($msOut)
$gzip.Close()
[System.IO.File]::WriteAllBytes("public\index.html", $msOut.ToArray())

$len = (Get-Item "public\index.html").Length
Write-Host "File written, length: $len bytes (should be 317213)"

$count = (Select-String -Path "public\index.html" -Pattern "data:image/webp;base64" -AllMatches).Matches.Count
Write-Host "Remaining broken webp icons: $count (should be 0)"
